            if (window.AlchemyFlasks?.aiming) window.AlchemyFlasks.setTarget(_mouseWorld.x * TILE, _mouseWorld.z * TILE); // Mouse ground-target cursor.
            const dx = _mouseWorld.x - player.x / TILE;
            const dz = _mouseWorld.z - player.y / TILE;
