        give: (itemKey, n = 1) => { inventory[itemKey] = (inventory[itemKey] || 0) + n; },
        place: placeDecorativeFurniture,
        sit: beginSitInteraction,
        endSit: endSitInteraction,
        get sitState() { return sitInteraction; },
